CREATE TABLE plants (plant_id INTEGER PRIMARY KEY, plant_name TEXT, city TEXT, country TEXT, opened_date TEXT);
CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT, segment TEXT, region TEXT, country TEXT);
CREATE TABLE dealers (dealer_id INTEGER PRIMARY KEY, dealer_name TEXT, region TEXT, city TEXT);
CREATE TABLE engines (engine_id INTEGER PRIMARY KEY, serial_no TEXT, model TEXT, plant_id INTEGER, build_date TEXT, customer_id INTEGER, horsepower INTEGER);
CREATE TABLE suppliers (supplier_id INTEGER PRIMARY KEY, supplier_name TEXT, country TEXT, rating REAL);
CREATE TABLE parts (part_id INTEGER PRIMARY KEY, part_name TEXT, category TEXT, unit_cost REAL, supplier_id INTEGER);
CREATE TABLE purchase_orders (po_id INTEGER PRIMARY KEY, supplier_id INTEGER, part_id INTEGER, qty INTEGER, order_date TEXT, expected_date TEXT, received_date TEXT, unit_price REAL);
CREATE TABLE inventory (plant_id INTEGER, part_id INTEGER, snapshot_date TEXT, qty_on_hand INTEGER);
CREATE TABLE employees (emp_id INTEGER PRIMARY KEY, name TEXT, role TEXT, manager_id INTEGER, plant_id INTEGER, hire_date TEXT, salary INTEGER);
CREATE TABLE crf (crf_id INTEGER PRIMARY KEY, customer_id INTEGER, dealer_id INTEGER, engine_id INTEGER, created_at TEXT, issue_type TEXT, status TEXT);
CREATE TABLE service_requests (sr_id INTEGER PRIMARY KEY, crf_id INTEGER, opened_at TEXT, closed_at TEXT, priority TEXT, status TEXT, technician_id INTEGER);
CREATE TABLE pir (pir_id INTEGER PRIMARY KEY, sr_id INTEGER, created_at TEXT, failure_code TEXT, root_cause TEXT, status TEXT);
CREATE TABLE claims (claim_id INTEGER PRIMARY KEY, pir_id INTEGER, dealer_id INTEGER, submitted_at TEXT, claim_amount REAL, approved_amount REAL, status TEXT);
CREATE TABLE credit_notes (cn_id INTEGER PRIMARY KEY, claim_id INTEGER, issued_at TEXT, amount REAL);
CREATE TABLE quality_defects (defect_id INTEGER PRIMARY KEY, engine_id INTEGER, part_id INTEGER, detected_at TEXT, stage TEXT, severity TEXT);
CREATE TABLE sensor_readings (reading_id INTEGER PRIMARY KEY, engine_id INTEGER, ts TEXT, temperature_c REAL, oil_pressure_kpa REAL, rpm INTEGER);
CREATE TABLE engine_daily_status (engine_id INTEGER, day TEXT, is_running INTEGER);
CREATE TABLE raw_orders_feed (event_id INTEGER PRIMARY KEY, order_id INTEGER, status TEXT, amount REAL, updated_at TEXT, ingested_at TEXT);
CREATE TABLE orders_current (order_id INTEGER PRIMARY KEY, status TEXT, amount REAL, updated_at TEXT);
CREATE TABLE etl_watermarks (pipeline TEXT PRIMARY KEY, last_loaded_at TEXT);
CREATE TABLE dim_customer_scd2 (customer_sk INTEGER PRIMARY KEY, customer_id INTEGER, segment TEXT, region TEXT, valid_from TEXT, valid_to TEXT, is_current INTEGER);
CREATE TABLE toy_a (id INTEGER, val TEXT);
CREATE TABLE toy_b (id INTEGER, val TEXT);
